// IRNews.jsx
import { useEffect } from "react";

const CODE = 5621;

export default function IRNews() {
  useEffect(() => {
    // ここで「HTMLが描かれたあと」に処理を走らせる
    const container = document.getElementById("irp-press-list");
    if (!container) {
      console.log("#irp-press-list が見つからないのでスキップ");
      return;
    }

    const created = [];

    const loadScript = (src) =>
      new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = src;
        s.async = true;
        s.onload = () => resolve(s);
        s.onerror = (e) => reject(e);
        document.body.appendChild(s);
        created.push(s);
      });

    (async () => {
      try {
        // 1) config.js / utils.js を読み込み（main.jsは使わない）
        await loadScript(`https://irpocket.com/${CODE}/irpocket/config.js`);
        await loadScript(`https://irpocket.com/${CODE}/irpocket/utils.js`);

        // 2) JSONP の受け口を用意
        //   release-all-all.js は ir20handler(data) を呼びます。
        // 　main.jsの記述を下記記述で代用
        window.ir20handler = function (data) {
          console.log("ir20handler called:", data);
          if (window.irpocket && typeof window.irpocket.handlerRelease === "function") {
            // ★ ここが「HTML描画後に irpocket.handlerRelease を動かす」本体
            window.irpocket.handlerRelease(container, data);
          } else {
            console.warn("irpocket.handlerRelease がありません");
          }
        };

        // 3) JSONP (release-all-all.js) を読み込み
        // 　main.jsの記述を下記記述で代用
        const ts = Date.now();
        await loadScript(
          `https://xml.irpocket.com/${CODE}/JS/release-all-all.js?${ts}`
        );
      } catch (e) {
        console.error("IRPocket 読み込み中にエラー:", e);
      }
    })();

    return () => {
      // お片付け（必要なら）
      created.forEach((el) => {
        try {
          el.remove();
        } catch {
          /* noop */
        }
      });
      delete window.ir20handler;
    };
  }, []);

  // HTMLの記述をJSX形式で記載
  // class → className に変換するのを忘れずに
  return (
    <>
      {/* IRPOCKET */}
      <div className="s-irNews__search humantechnology-c-irSearch">
        <div className="c-irSearch__head">
          <div className="c-irSearch__ttl">YEAR</div>
          <select id="irp-press-navi" className="c-irSearch__select"></select>
        </div>
        <ul id="irnews-category" className="c-irSearch__category"></ul>
      </div>
      <div
        id="irp-press-list"
        className="s-irNews__news humantechnology-c-irNews"
      ></div>
      <div
        id="irp-press-page"
        className="s-irNews__pagination humantechnology-c-irPagination"
      >
        <ul id="irp-press-page-body"></ul>
      </div>
      {/* /IRPOCKET */}
    </>
  );
}
